CREATE TABLE book (
    id INTEGER PRIMARY KEY,
    name_en TEXT NOT NULL,
    name_cn TEXT NOT NULL,
    testament TEXT NOT NULL,
    order_index INTEGER NOT NULL
, abbr_en TEXT, abbr_cn TEXT);
