CREATE TABLE verse (
    id TEXT PRIMARY KEY,
    book_id INTEGER NOT NULL,
    chapter INTEGER NOT NULL,
    verse INTEGER NOT NULL,
    text_en TEXT NOT NULL,
    text_cn TEXT NOT NULL,
    FOREIGN KEY (book_id) REFERENCES book(id)
);
INSERT INTO verse VALUES('Mt.1.1',47,1,1,'An account of the genealogy of Jesus the Messiah, the son of David, the son of Abraham.','亚巴郎之子，达味之子耶稣基督的族谱：');
INSERT INTO verse VALUES('Mt.1.2',47,1,2,'Abraham was the father of Isaac, and Isaac the father of Jacob, and Jacob the father of Judah and his brothers,','亚巴郎生依撒格，依撒格生雅各伯，雅各伯生犹大和他的兄弟们；');
INSERT INTO verse VALUES('Mt.1.3',47,1,3,'and Judah the father of Perez and Zerah by Tamar, and Perez the father of Hezron, and Hezron the father of Aram,','犹大由塔玛尔生培勒兹和则辣黑，培勒兹生赫兹龙，赫兹龙生阿兰，');
INSERT INTO verse VALUES('Mt.1.4',47,1,4,'and Aram the father of Aminadab, and Aminadab the father of Nahshon, and Nahshon the father of Salmon,','阿兰生阿米纳达布，阿米纳达布生纳赫雄，纳赫雄生撒耳孟，');
INSERT INTO verse VALUES('Mt.1.5',47,1,5,'and Salmon the father of Boaz by Rahab, and Boaz the father of Obed by Ruth, and Obed the father of Jesse,','撒耳孟由辣哈布生波阿次，波阿次由卢德生敖贝得，敖贝得生叶瑟，');
INSERT INTO verse VALUES('Mt.1.6',47,1,6,'and Jesse the father of King David. And David was the father of Solomon by the wife of Uriah,','叶瑟生达味王。达味由乌黎雅的妻子生撒罗满，');
INSERT INTO verse VALUES('Mt.1.7',47,1,7,'and Solomon the father of Rehoboam, and Rehoboam the father of Abijah, and Abijah the father of Asaph,','撒罗满生勒哈贝罕，勒哈贝罕生阿彼雅，阿彼雅生阿撒，');
INSERT INTO verse VALUES('Mt.1.8',47,1,8,'and Asaph the father of Jehoshaphat, and Jehoshaphat the father of Joram, and Joram the father of Uzziah,','阿撒生约沙法特，约沙法特生约兰，约兰生乌齐雅，');
INSERT INTO verse VALUES('Mt.1.9',47,1,9,'and Uzziah the father of Jotham, and Jotham the father of Ahaz, and Ahaz the father of Hezekiah,','乌齐雅生约堂，约堂生阿哈次，阿哈次生希则克雅，');
INSERT INTO verse VALUES('Mt.1.10',47,1,10,'and Hezekiah the father of Manasseh, and Manasseh the father of Amos, and Amos the father of Josiah,','希则克雅生默纳舍，默纳舍生阿孟，阿孟生约史雅，');
INSERT INTO verse VALUES('Mt.1.11',47,1,11,'and Josiah the father of Jechoniah and his brothers, at the time of the deportation to Babylon.','约史雅在巴比伦流徙期间生耶苛尼雅和他的兄弟们。');
INSERT INTO verse VALUES('Mt.1.12',47,1,12,'And after the deportation to Babylon: Jechoniah was the father of Salathiel, and Salathiel the father of Zerubbabel,','流徙巴比伦以后，耶苛尼雅生沙耳提耳，沙耳提耳生则鲁巴贝耳，');
INSERT INTO verse VALUES('Mt.1.13',47,1,13,'and Zerubbabel the father of Abiud, and Abiud the father of Eliakim, and Eliakim the father of Azor,','则鲁巴贝耳生阿彼乌得，阿彼乌得生厄里雅金，厄里雅金生阿左尔。');
INSERT INTO verse VALUES('Mt.1.14',47,1,14,'and Azor the father of Zadok, and Zadok the father of Achim, and Achim the father of Eliud,','阿左尔生匝多克，匝多克生阿歆（xīn），阿歆生厄里乌得，');
INSERT INTO verse VALUES('Mt.1.15',47,1,15,'and Eliud the father of Eleazar, and Eleazar the father of Matthan, and Matthan the father of Jacob,','厄里乌得生厄肋阿匝尔，厄肋阿匝尔生玛堂，玛堂生雅各伯，');
INSERT INTO verse VALUES('Mt.1.16',47,1,16,'and Jacob the father of Joseph the husband of Mary, of whom Jesus was born, who is called the Messiah.','雅各伯生若瑟，玛利亚的丈夫，玛利亚生耶稣，他称为基督。');
INSERT INTO verse VALUES('Mt.1.17',47,1,17,'So all the generations from Abraham to David are fourteen generations; and from David to the deportation to Babylon, fourteen generations; and from the deportation to Babylon to the Messiah, fourteen generations.','所以从亚巴郎到达味共十四代，从达味到流徙巴比伦共十四代，从流徙巴比伦到基督共十四代。');
INSERT INTO verse VALUES('Mt.1.18',47,1,18,'Now the birth of Jesus the Messiah took place in this way. When his mother Mary had been engaged to Joseph, but before they lived together, she was found to be with child from the Holy Spirit.','耶稣基督的诞生是这样的：他的母亲玛利亚许配于若瑟后，在同居前，她因圣神有孕的事已显示出来。');
INSERT INTO verse VALUES('Mt.1.19',47,1,19,'Her husband Joseph, being a righteous man and unwilling to expose her to public disgrace, planned to dismiss her quietly.','她的丈夫若瑟，因是义人，不愿公开羞辱她，有意暗暗地休退她。');
INSERT INTO verse VALUES('Mt.1.20',47,1,20,'But just when he had resolved to do this, an angel of the Lord appeared to him in a dream and said, “Joseph, son of David, do not be afraid to take Mary as your wife, for the child conceived in her is from the Holy Spirit.','当他在思虑这事时，看，在梦中上主的天使显现给他说：“达味之子若瑟，不要怕娶你的妻子玛利亚，因为那在她内受生的，是出于圣神。');
INSERT INTO verse VALUES('Mt.1.21',47,1,21,'She will bear a son, and you are to name him Jesus, for he will save his people from their sins.”','她要生一个儿子，你要给他起名叫耶稣，因为他要把自己的民族，由他们的罪恶中拯救出来。”');
INSERT INTO verse VALUES('Mt.1.22',47,1,22,'All this took place to fulfill what had been spoken by the Lord through the prophet:','这一切事的发生，是为应验上主藉先知所说的话：');
INSERT INTO verse VALUES('Mt.1.23',47,1,23,'“Look, the virgin shall conceive and bear a son,    and they shall name him Emmanuel,” which means, “God is with us.”','“看，一位贞女，将怀孕生子，人将称他的名字为厄玛奴耳，意思是：天主与我们同在。');
INSERT INTO verse VALUES('Mt.1.24',47,1,24,'When Joseph awoke from sleep, he did as the angel of the Lord commanded him; he took her as his wife,','若瑟从睡梦中醒来，就照上主的天使所嘱咐的办了，娶了他的妻子；');
INSERT INTO verse VALUES('Mt.1.25',47,1,25,'but had no marital relations with her until she had borne a son; and he named him Jesus.','若瑟虽然没有认识她，她就生了一个儿子，给他起名叫耶稣。');
INSERT INTO verse VALUES('2K.4.1',12,4,1,'Now the wife of a member of the company of prophets cried to Elisha, “Your servant my husband is dead; and you know that your servant feared the Lord, but a creditor has come to take my two children as slaves.”','有一个先知弟子的妻子，前来哀求厄里叟说：“你的仆人，我的丈夫死了，你知道你的仆人是一个敬畏上主的人；现在债主前来，要带走我的两个孩子，作他的奴隶。”');
INSERT INTO verse VALUES('2K.4.2',12,4,2,'Elisha said to her, “What shall I do for you? Tell me, what do you have in the house?” She answered, “Your servant has nothing in the house, except a jar of oil.”','厄里叟对她说：“我能为你做什么？你告诉我：你家里还有什么？”她答说：“婢女家里除一瓶油外，什么也没有。”');
INSERT INTO verse VALUES('2K.4.3',12,4,3,'He said, “Go outside, borrow vessels from all your neighbors, empty vessels and not just a few.','厄里叟说：“你去，到外面向你所有的邻居借些空器皿，不要少借；');
INSERT INTO verse VALUES('2K.4.4',12,4,4,'Then go in, and shut the door behind you and your children, and start pouring into all these vessels; when each is full, set it aside.”','然后回家，关上门，你和你的儿子在家里，将油倒在所有的那些器皿内，把装满了的，放在一边。”');
INSERT INTO verse VALUES('2K.4.5',12,4,5,'So she left him and shut the door behind her and her children; they kept bringing vessels to her, and she kept pouring.','她于是辞别厄里叟，回去照办。她和她的儿子关上门，儿子给她递器皿，她只顾倒油，');
INSERT INTO verse VALUES('2K.4.6',12,4,6,'When the vessels were full, she said to her son, “Bring me another vessel.” But he said to her, “There are no more.” Then the oil stopped flowing.','器皿都装满了，她对儿子说：“再递给我器皿！”儿子答说：“没有了。”同时油也止住了。');
INSERT INTO verse VALUES('2K.4.7',12,4,7,'She came and told the man of God, and he said, “Go sell the oil and pay your debts, and you and your children can live on the rest.”','妇人就去告诉天主的人。厄里叟对她说：“你去把油卖了，还你的债；剩下的，你和你的儿子可用来过活。”');
INSERT INTO verse VALUES('2K.4.8',12,4,8,'One day Elisha was passing through Shunem, where a wealthy woman lived, who urged him to have a meal. So whenever he passed that way, he would stop there for a meal.','有一天，厄里叟路过叔能，那里有一个富贵的妇人，曾挽留他吃饭；因此，厄里叟每次路过那里，总到她家里吃饭。');
INSERT INTO verse VALUES('2K.4.9',12,4,9,'She said to her husband, “Look, I am sure that this man who regularly passes our way is a holy man of God.','妇人对丈夫说：“现在我看出：这个时常路过我们这里的天主的人，是位圣者。');
INSERT INTO verse VALUES('2K.4.10',12,4,10,'Let us make a small roof chamber with walls, and put there for him a bed, a table, a chair, and a lamp, so that he can stay there whenever he comes to us.”','我们可以在房顶上，给他盖一间小房，里面放一张床，一张桌子，一把椅子和一盏灯；这样，他几时来到我们这里，可在那里休息。”');
INSERT INTO verse VALUES('2K.4.11',12,4,11,'One day when he came there, he went up to the chamber and lay down there.','一天，厄里叟又到了那里，就进入那间小房休息。');
INSERT INTO verse VALUES('2K.4.12',12,4,12,'He said to his servant Gehazi, “Call the Shunammite woman.” When he had called her, she stood before him.','厄里叟吩咐自己的仆人革哈齐说：“你叫这位叔能妇人来。”仆人叫了妇人来，妇人站在先知面前，');
INSERT INTO verse VALUES('2K.4.13',12,4,13,'He said to him, “Say to her, Since you have taken all this trouble for us, what may be done for you? Would you have a word spoken on your behalf to the king or to the commander of the army?” She answered, “I live among my own people.”','厄里叟吩咐仆人说：“现在你对她说：看，你照顾我们既然这样周到，我们可为你作什么事呢？要不要我们在君王或军长前为你说句话？”那妇人答说：“我住在我本国人民中很平安。”');
INSERT INTO verse VALUES('2K.4.14',12,4,14,'He said, “What then may be done for her?” Gehazi answered, “Well, she has no son, and her husband is old.”','厄里叟就问革哈齐：“我们究竟能为她作什么？”革哈齐说：“可怜她没有儿子，丈夫又老了。”');
INSERT INTO verse VALUES('2K.4.15',12,4,15,'He said, “Call her.” When he had called her, she stood at the door.','厄里叟说：“快再叫她来！”仆人又将妇人叫来，这次她却站在门口，');
INSERT INTO verse VALUES('2K.4.16',12,4,16,'He said, “At this season, in due time, you shall embrace a son.” She replied, “No, my lord, O man of God; do not deceive your servant.”','厄里叟对她说：“明年这时，你必怀抱着一个儿子。”妇人答说：“我主，天主的人哪！不会！你别哄骗你的婢女！”');
INSERT INTO verse VALUES('2K.4.17',12,4,17,'The woman conceived and bore a son at that season, in due time, as Elisha had declared to her.','这妇人果然怀了孕；过了一年，在厄里叟对她所说的时候，生了一个儿子。');
INSERT INTO verse VALUES('2K.4.18',12,4,18,'When the child was older, he went out one day to his father among the reapers.','孩子渐渐长大，一天，他出去到收割的人那里找他父亲，');
INSERT INTO verse VALUES('2K.4.19',12,4,19,'He complained to his father, “Oh, my head, my head!” The father said to his servant, “Carry him to his mother.”','孩子忽然对他父亲喊说：“我的头啊！我的头啊！”他父亲吩咐仆人说：“把孩子送到他母亲那里去！”');
INSERT INTO verse VALUES('2K.4.20',12,4,20,'He carried him and brought him to his mother; the child sat on her lap until noon, and he died.','仆人将他抱起，送给他母亲，孩子坐在母亲膝上，到了中午，就死了。');
INSERT INTO verse VALUES('2K.4.21',12,4,21,'She went up and laid him on the bed of the man of God, closed the door on him, and left.','他母亲遂上了楼，将孩子放在天主的人的床上，关上门，出来，');
INSERT INTO verse VALUES('2K.4.22',12,4,22,'Then she called to her husband, and said, “Send me one of the servants and one of the donkeys, so that I may quickly go to the man of God and come back again.”','叫自己的丈夫来说：“请你给我派一个仆人，牵一匹驴来，我要快去见见天主的人，就回来。”');
INSERT INTO verse VALUES('2K.4.23',12,4,23,'He said, “Why go to him today? It is neither new moon nor sabbath.” She said, “It will be all right.”','她丈夫说：“为什么今天要去见他，既不是朔日，又不是安息日？”妇人答说：“你放心好了！”');
INSERT INTO verse VALUES('2K.4.24',12,4,24,'Then she saddled the donkey and said to her servant, “Urge the animal on; do not hold back for me unless I tell you.”','于是，她把驴备好，对仆人说：“你快赶着走，我若不吩咐，在路上不要停下来。”');
INSERT INTO verse VALUES('2K.4.25',12,4,25,'So she set out, and came to the man of God at Mount Carmel. When the man of God saw her coming, he said to Gehazi his servant, “Look, there is the Shunammite woman;','妇人于是来到加尔默耳山见天主的人。天主的人自远处看见她，就对自己的仆人革哈齐说：“看，那是叔能妇人！');
INSERT INTO verse VALUES('2K.4.26',12,4,26,'run at once to meet her, and say to her, Are you all right? Is your husband all right? Is the child all right?” She answered, “It is all right.”','现在你跑去迎接她，向她问安说：你好吗？你的丈夫好吗？你的孩子好吗？”她回答说：“好。”');
INSERT INTO verse VALUES('2K.4.27',12,4,27,'When she came to the man of God at the mountain, she caught hold of his feet. Gehazi approached to push her away. But the man of God said, “Let her alone, for she is in bitter distress; the Lord has hidden it from me and has not told me.”','妇人上到山上，来到天主的人跟前，就抱住他的脚；革哈齐前来想推开她，可是天主的人说：“由她吧！因为她心中很痛苦；上主隐瞒了我，什么也没有告诉我。”');
INSERT INTO verse VALUES('2K.4.28',12,4,28,'Then she said, “Did I ask my lord for a son? Did I not say, Do not mislead me?”','那妇人说：“我何尝向我主求过一个儿子？我岂不是说过：你不要哄骗我吗？”');
INSERT INTO verse VALUES('2K.4.29',12,4,29,'He said to Gehazi, “Gird up your loins, and take my staff in your hand, and go. If you meet anyone, give no greeting, and if anyone greets you, do not answer; and lay my staff on the face of the child.”','厄里叟对革哈齐说：“你束上腰，手里拿着我的棍杖前去；不论遇见谁，不要向他请安；不论谁向你请安，你也不要回答。你去把我的棍杖放在孩子的脸上。”');
INSERT INTO verse VALUES('2K.4.30',12,4,30,'Then the mother of the child said, “As the Lord lives, and as you yourself live, I will not leave without you.” So he rose up and followed her.','孩子的母亲说：“我指着永生的上主及你的性命起誓：你不去，我决不离开。”厄里叟就起身跟她去了。');
INSERT INTO verse VALUES('2K.4.31',12,4,31,'Gehazi went on ahead and laid the staff on the face of the child, but there was no sound or sign of life. He came back to meet him and told him, “The child has not awakened.”','革哈齐在他们以先去了。将棍杖放在孩子的脸上，但是没有声音，没有反应；他便回来见厄里叟，告诉他说：“孩子没有醒来。”');
INSERT INTO verse VALUES('2K.4.32',12,4,32,'When Elisha came into the house, he saw the child lying dead on his bed.','厄里叟一来到她家，看见孩子死了，躺在自己的床上，');
INSERT INTO verse VALUES('2K.4.33',12,4,33,'So he went in and closed the door on the two of them, and prayed to the Lord.','就进去，关上门，房内只有他和孩子；先知先哀求了上主，');
INSERT INTO verse VALUES('2K.4.34',12,4,34,'Then he got up on the bed and lay upon the child, putting his mouth upon his mouth, his eyes upon his eyes, and his hands upon his hands; and while he lay bent over him, the flesh of the child became warm.','然后上床，伏在孩子身上，自己的口对住孩子的口，自己的眼对住孩子的眼，自己的手按住孩子的手，屈身伏在孩子身上，孩子的肉身便渐渐温暖了。');
INSERT INTO verse VALUES('2K.4.35',12,4,35,'He got down, walked once to and fro in the room, then got up again and bent over him; the child sneezed seven times, and the child opened his eyes.','然后他下来，在屋内来回走了一趟；又上去，屈身伏在孩子身上，对着孩子呵了七口气，孩子就睁开了眼睛。');
INSERT INTO verse VALUES('2K.4.36',12,4,36,'Elisha summoned Gehazi and said, “Call the Shunammite woman.” So he called her. When she came to him, he said, “Take your son.”','厄里叟叫革哈齐来，对他说：“你叫那叔能妇人来。”他便去叫那妇人，妇人就来了。厄里叟说：“抱起你的孩子来！”');
INSERT INTO verse VALUES('2K.4.37',12,4,37,'She came and fell at his feet, bowing to the ground; then she took her son and left.','妇人一进来，就俯伏在他脚前，叩首至地；然后起来，抱起自己的孩子出去了。');
INSERT INTO verse VALUES('2K.4.38',12,4,38,'When Elisha returned to Gilgal, there was a famine in the land. As the company of prophets was sitting before him, he said to his servant, “Put the large pot on, and make some stew for the company of prophets.”','厄里叟又来到基耳加耳，那地方正遭受饥荒；众先知的弟子坐在他面前，他吩咐自己的仆人说：“你在火上放上一个火锅，给众先知的弟子煮些菜汤。”');
INSERT INTO verse VALUES('2K.4.39',12,4,39,'One of them went out into the field to gather herbs; he found a wild vine and gathered from it a lapful of wild gourds, and came and cut them up into the pot of stew, not knowing what they were.','有一个弟子出去到田间采菜，看见一棵野葡萄树，从上面采了一满兜野果子回来，切碎放在菜锅里，并不知道是什么东西。');
INSERT INTO verse VALUES('2K.4.40',12,4,40,'They served some for the men to eat. But while they were eating the stew, they cried out, “O man of God, there is death in the pot!” They could not eat it.','以后，他们把菜汤倒出来给众人吃。众人一尝这菜汤，都喊叫说：“天主的人，锅里有致死的毒物啊！”众人都不能吃。');
INSERT INTO verse VALUES('2K.4.41',12,4,41,'He said, “Then bring some flour.” He threw it into the pot, and said, “Serve the people and let them eat.” And there was nothing harmful in the pot.','那时厄里叟说：“拿点面来！”他把面撒在锅里说：“倒出来给众人吃吧！”锅里就再没有什么毒了。');
INSERT INTO verse VALUES('2K.4.42',12,4,42,'A man came from Baal-shalishah, bringing food from the first fruits to the man of God: twenty loaves of barley and fresh ears of grain in his sack. Elisha said, “Give it to the people and let them eat.”','有一个人从巴耳沙里沙来，在自己的行囊里，给天主的人带来了初熟大麦作的二十个饼和一些新麦穗。厄里叟说：“分给众人吃吧！”');
INSERT INTO verse VALUES('2K.4.43',12,4,43,'But his servant said, “How can I set this before a hundred people?” So he repeated, “Give it to the people and let them eat, for thus says the Lord, ‘They shall eat and have some left.’”','仆人说：“我怎能将这一点东西摆在一百人面前呢？”厄里叟说：“你尽管分给众人吃，因为上主这样说：众人吃了，还有剩余。”');
INSERT INTO verse VALUES('2K.4.44',12,4,44,'He set it before them, they ate, and had some left, according to the word of the Lord.','于是仆人将食物摆在众人面前，他们都吃了，并且还有剩余，全应验了上主的话。');
INSERT INTO verse VALUES('Mt.10.1',47,10,1,'Then Jesus summoned his twelve disciples and gave them authority over unclean spirits, to cast them out, and to cure every disease and every sickness.','耶稣将他的十二门徒叫来，授给他们制伏邪魔的权柄，可以驱逐邪魔，医治各种病症，各种疾苦。');
INSERT INTO verse VALUES('Mt.10.2',47,10,2,'These are the names of the twelve apostles: first, Simon, also known as Peter, and his brother Andrew; James son of Zebedee, and his brother John;','这是十二宗徒的名字：第一个是称为伯多禄的西满，和他的兄弟安德肋，载伯德的儿子雅各伯和他的弟弟若望，');
INSERT INTO verse VALUES('Mt.10.3',47,10,3,'Philip and Bartholomew; Thomas and Matthew the tax collector; James son of Alphaeus, and Thaddaeus;','斐理伯和巴尔多禄茂，多默和税吏玛窦，阿耳斐的儿子雅各伯和达陡，');
INSERT INTO verse VALUES('Mt.10.4',47,10,4,'Simon the Cananaean, and Judas Iscariot, the one who betrayed him.','热诚者西满和负卖耶稣的犹达斯依斯加略。');
INSERT INTO verse VALUES('Mt.10.5',47,10,5,'These twelve Jesus sent out with the following instructions: “Go nowhere among the Gentiles, and enter no town of the Samaritans,','耶稣派遣这十二人，嘱咐他们说：外邦人的路，你们不要走；撒玛黎雅人的城你们不要进，');
INSERT INTO verse VALUES('Mt.10.6',47,10,6,'but go rather to the lost sheep of the house of Israel.','你们宁可往以色列家迷失了的羊那里去。');
INSERT INTO verse VALUES('Mt.10.7',47,10,7,'As you go, proclaim the good news, ‘The kingdom of heaven has come near.’','你们在路上应宣讲说：天国临近了。');
INSERT INTO verse VALUES('Mt.10.8',47,10,8,'Cure the sick, raise the dead, cleanse the lepers, cast out demons. You received without payment; give without payment.','病人，你们要治好；死人，你们要复活；癞病人，你们要洁净；魔鬼，你们要驱逐；你们白白得来的，也要白白分施。');
INSERT INTO verse VALUES('Mt.10.9',47,10,9,'Take no gold, or silver, or copper in your belts,','你们不要在腰带里备下金、银、铜钱；');
INSERT INTO verse VALUES('Mt.10.10',47,10,10,'no bag for your journey, or two tunics, or sandals, or a staff; for laborers deserve their food.','路上不要带口袋，也不要带两件内衣，也不要穿鞋，也不要带棍杖，因为工人自当有他的食物。');
INSERT INTO verse VALUES('Mt.10.11',47,10,11,'Whatever town or village you enter, find out who in it is worthy, and stay there until you leave.','你们不论进了哪一城或哪一村，查问其中谁是当得起的，就住在那里，直到你们离去。');
INSERT INTO verse VALUES('Mt.10.12',47,10,12,'As you enter the house, greet it.','你们进那一家时，要向它请安。');
INSERT INTO verse VALUES('Mt.10.13',47,10,13,'If the house is worthy, let your peace come upon it; but if it is not worthy, let your peace return to you.','倘若这一家是堪当的，你们的平安就必降临到这一家；倘若是不堪当的，你们的平安仍归于你们。');
INSERT INTO verse VALUES('Mt.10.14',47,10,14,'If anyone will not welcome you or listen to your words, shake off the dust from your feet as you leave that house or town.','谁若不接待你们，也不听你们的话，当你们从那一家或那一城出来时，应把尘土由你们的脚上拂去。');
INSERT INTO verse VALUES('Mt.10.15',47,10,15,'Truly I tell you, it will be more tolerable for the land of Sodom and Gomorrah on the day of judgment than for that town.','我实在告诉你们：在审判的日子，索多玛和哈摩辣地所受的惩罚，比那座城所受的还要轻。');
INSERT INTO verse VALUES('Mt.10.16',47,10,16,'“See, I am sending you out like sheep into the midst of wolves; so be wise as serpents and innocent as doves.','看，我派遣你们好像羊进入狼群中，所以你们要机警如同蛇，纯朴如同鸽子。');
INSERT INTO verse VALUES('Mt.10.17',47,10,17,'Beware of them, for they will hand you over to councils and flog you in their synagogues;','你们要提防世人，因为他们要把你们交给公议会，要在他们的会堂里鞭打你们；');
INSERT INTO verse VALUES('Mt.10.18',47,10,18,'and you will be dragged before governors and kings because of me, as a testimony to them and the Gentiles.','并且你们要为我的缘故，被带到总督和君王前，对他们和外邦人作证。');
INSERT INTO verse VALUES('Mt.10.19',47,10,19,'When they hand you over, do not worry about how you are to speak or what you are to say; for what you are to say will be given to you at that time;','当人把你们交出时，你们不要思虑：怎么说，或说什么，因为在那时刻，自会赐给你们应说什么。');
INSERT INTO verse VALUES('Mt.10.20',47,10,20,'for it is not you who speak, but the Spirit of your Father speaking through you.','因为说话的不是你们，而是你们父的圣神在你们内说话。');
INSERT INTO verse VALUES('Mt.10.21',47,10,21,'Brother will betray brother to death, and a father his child, and children will rise against parents and have them put to death;','兄弟要将兄弟，父亲要将儿子置于死地，儿女也要起来反对父母，要将他们害死。');
INSERT INTO verse VALUES('Mt.10.22',47,10,22,'and you will be hated by all because of my name. But the one who endures to the end will be saved.','你们为了我的名字，要为众人所恼恨；唯独坚持到底的，才可得救。');
INSERT INTO verse VALUES('Mt.10.23',47,10,23,'When they persecute you in one town, flee to the next; for truly I tell you, you will not have gone through all the towns of Israel before the Son of Man comes.','但是，几时人们在这城迫害你们，你们就逃往另一城去；我实在告诉你们：直到人子来到时，你们还未走完以色列的城邑。');
INSERT INTO verse VALUES('Mt.10.24',47,10,24,'“A disciple is not above the teacher, nor a slave above the master;','没有徒弟胜过师傅的，也没有仆人胜过他主人的；');
INSERT INTO verse VALUES('Mt.10.25',47,10,25,'it is enough for the disciple to be like the teacher, and the slave like the master. If they have called the master of the house Beelzebul, how much more will they malign those of his household!','徒弟能如他的师傅一样，仆人能如他的主人一样，也就够了。若人们称家主为“贝耳则步”，对他的家人更该怎样呢？');
INSERT INTO verse VALUES('Mt.10.26',47,10,26,'“So have no fear of them; for nothing is covered up that will not be uncovered, and nothing secret that will not become known.','所以，你们不要害怕他们；因为没有遮掩的事，将来不被揭露的；也没有隐藏的事，将来不被知道的。');
INSERT INTO verse VALUES('Mt.10.27',47,10,27,'What I say to you in the dark, tell in the light; and what you hear whispered, proclaim from the housetops.','我在暗中给你们所说的，你们要在光天化日之下报告出来；你们由耳语所听到的，要在屋顶上张扬出来。');
INSERT INTO verse VALUES('Mt.10.28',47,10,28,'Do not fear those who kill the body but cannot kill the soul; rather fear him who can destroy both soul and body in hell.','你们不要害怕那杀害肉身，而不能杀害灵魂的；但更要害怕那能使灵魂和肉身陷于地狱中的。');
INSERT INTO verse VALUES('Mt.10.29',47,10,29,'Are not two sparrows sold for a penny? Yet not one of them will fall to the ground apart from your Father.','两只麻雀不是卖一个铜钱吗？但若没有你们天父的许可，它们中连一只也不会掉在地上。');
INSERT INTO verse VALUES('Mt.10.30',47,10,30,'And even the hairs of your head are all counted.','就是你们的头发，也都一一数过了。');
INSERT INTO verse VALUES('Mt.10.31',47,10,31,'So do not be afraid; you are of more value than many sparrows.','所以，你们不要害怕；你们比许多麻雀还贵重呢！');
INSERT INTO verse VALUES('Mt.10.32',47,10,32,'“Everyone therefore who acknowledges me before others, I also will acknowledge before my Father in heaven;','凡在人前承认我的，我在我天上的父前也必承认他；');
INSERT INTO verse VALUES('Mt.10.33',47,10,33,'but whoever denies me before others, I also will deny before my Father in heaven.','但谁若在人前否认我，我在我天上的父前也必否认他。');
INSERT INTO verse VALUES('Mt.10.34',47,10,34,'“Do not think that I have come to bring peace to the earth; I have not come to bring peace, but a sword.','你们不要以为我来，是为把平安带到地上；我来不是为带平安，而是带刀剑，');
INSERT INTO verse VALUES('Mt.10.35',47,10,35,'For I have come to set a man against his father,and a daughter against her mother,and a daughter-in-law against her mother-in-law;','因为我来，是为叫人脱离自己的父亲，女儿脱离自己的母亲，儿媳脱离自己的婆母；');
INSERT INTO verse VALUES('Mt.10.36',47,10,36,'and one’s foes will be members of one’s own household.','所以，人的仇敌，就是自己的家人。');
INSERT INTO verse VALUES('Mt.10.37',47,10,37,'Whoever loves father or mother more than me is not worthy of me; and whoever loves son or daughter more than me is not worthy of me;','谁爱父亲或母亲超过我，不配是我的；谁爱儿子或女儿超过我，不配是我的。');
INSERT INTO verse VALUES('Mt.10.38',47,10,38,'and whoever does not take up the cross and follow me is not worthy of me.','谁不背起自己的十字架跟随我，不配是我的。');
INSERT INTO verse VALUES('Mt.10.39',47,10,39,'Those who find their life will lose it, and those who lose their life for my sake will find it.','谁获得自己的性命，必要丧失性命；谁为我的缘故，丧失了自己的性命，必要获得性命。');
INSERT INTO verse VALUES('Mt.10.40',47,10,40,'“Whoever welcomes you welcomes me, and whoever welcomes me welcomes the one who sent me.','谁接纳你们，就是接纳我；谁接纳我，就是接纳那派遣我来的。');
INSERT INTO verse VALUES('Mt.10.41',47,10,41,'Whoever welcomes a prophet in the name of a prophet will receive a prophet’s reward; and whoever welcomes a righteous person in the name of a righteous person will receive the reward of the righteous;','谁接纳一位先知，因为他是先知，将领受先知的赏报；谁接纳一位义人，因他是义人，将领受义人的赏报。');
INSERT INTO verse VALUES('Mt.10.42',47,10,42,'and whoever gives even a cup of cold water to one of these little ones in the name of a disciple—truly I tell you, none of these will lose their reward.”','谁若只给这些小子中的一个，一杯凉水喝，因他是门徒，我实在告诉你们，他决失不了他的赏报。');
INSERT INTO verse VALUES('Rom.6.1',52,6,1,'What then are we to say? Should we continue in sin in order that grace may abound?','那么，我们可说什么呢？我们要常留在罪恶中，好叫恩宠洋溢吗？');
INSERT INTO verse VALUES('Rom.6.2',52,6,2,'By no means! How can we who died to sin go on living in it?','断乎不可！我们这些死于罪恶的人，如何还能在罪恶中生活呢？');
INSERT INTO verse VALUES('Rom.6.3',52,6,3,'Do you not know that all of us who have been baptized into Christ Jesus were baptized into his death?','难道你们不知道：我们受过洗归于基督耶稣的人，就是受洗归于他的死亡吗？');
INSERT INTO verse VALUES('Rom.6.4',52,6,4,'Therefore we have been buried with him by baptism into death, so that, just as Christ was raised from the dead by the glory of the Father, so we too might walk in newness of life.','我们藉着洗礼已归于死亡与他同葬了，为的是基督怎样藉着父的光荣，从死者中复活了，我们也怎样在新生活中度生。');
INSERT INTO verse VALUES('Rom.6.5',52,6,5,'For if we have been united with him in a death like his, we will certainly be united with him in a resurrection like his.','如果我们藉着同他相似的死亡，已与他结合，也要藉着同他相似的复活与他结合，');
INSERT INTO verse VALUES('Rom.6.6',52,6,6,'We know that our old self was crucified with him so that the body of sin might be destroyed, and we might no longer be enslaved to sin.','因为我们知道，我们的旧人已与他同钉在十字架上了，使那属罪恶的自我消逝，好叫我们不再作罪恶的奴隶，');
INSERT INTO verse VALUES('Rom.6.7',52,6,7,'For whoever has died is freed from sin.','因为已死的人，便脱离了罪恶。');
INSERT INTO verse VALUES('Rom.6.8',52,6,8,'But if we have died with Christ, we believe that we will also live with him.','所以，如果我们与基督同死，我们相信也要与他同生，');
INSERT INTO verse VALUES('Rom.6.9',52,6,9,'We know that Christ, being raised from the dead, will never die again; death no longer has dominion over him.','因为我们知道：基督既从死者中复活，就不再死；死亡不再统治他了，');
INSERT INTO verse VALUES('Rom.6.10',52,6,10,'The death he died, he died to sin, once for all; but the life he lives, he lives to God.','因为他死，是死于罪恶，仅仅一次；他活，是活于天主。');
INSERT INTO verse VALUES('Rom.6.11',52,6,11,'So you also must consider yourselves dead to sin and alive to God in Christ Jesus.','你们也要这样看自己是死于罪恶，在基督耶稣内活于天主的人。');
INSERT INTO verse VALUES('Rom.6.12',52,6,12,'Therefore, do not let sin exercise dominion in your mortal bodies, to make you obey their passions.','所以不要让罪恶在你们必死的身体上为王，致令你们顺从它的情欲，');
INSERT INTO verse VALUES('Rom.6.13',52,6,13,'No longer present your members to sin as instruments of wickedness, but present yourselves to God as those who have been brought from death to life, and present your members to God as instruments of righteousness.','也不要把你们的肢体交与罪恶，作不义的武器；但该将你们自己献于天主，有如从死者中复活的人，将你们的肢体献于天主，当作正义的武器：');
INSERT INTO verse VALUES('Rom.6.14',52,6,14,'For sin will have no dominion over you, since you are not under law but under grace.','罪恶不应再统治你们，因为你们已不在法律权下，而是在恩宠权下。');
INSERT INTO verse VALUES('Rom.6.15',52,6,15,'What then? Should we sin because we are not under law but under grace? By no means!','那么，我们因为不在法律权下，而在恩宠权下，就可以犯罪吗？绝对不可！');
INSERT INTO verse VALUES('Rom.6.16',52,6,16,'Do you not know that if you present yourselves to anyone as obedient slaves, you are slaves of the one whom you obey, either of sin, which leads to death, or of obedience, which leads to righteousness?','难道你们不知道：你们将自己献给谁当奴隶，而服从他，就成了你们所服从者的奴隶，或作罪恶的奴隶，以致死亡；或作顺命的奴隶，以得正义吗？');
INSERT INTO verse VALUES('Rom.6.17',52,6,17,'But thanks be to God that you, having once been slaves of sin, have become obedient from the heart to the form of teaching to which you were entrusted,','感谢天主，虽然你们曾作过罪恶的奴隶，现今你们却从心里听从那传给你们的教理规范，');
INSERT INTO verse VALUES('Rom.6.18',52,6,18,'and that you, having been set free from sin, have become slaves of righteousness.','脱离罪恶，获得了自由，作了正义的奴隶。');
INSERT INTO verse VALUES('Rom.6.19',52,6,19,'I am speaking in human terms because of your natural limitations. For just as you once presented your members as slaves to impurity and to greater and greater iniquity, so now present your members as slaves to righteousness for sanctification.','为了你们本性的软弱，我且按常情来说：你们从前怎样将你们的肢体当作奴隶，献于不洁和不法，行不法的事；如今也要怎样将你们的肢体当作奴隶，献于正义，行圣善的事。');
INSERT INTO verse VALUES('Rom.6.20',52,6,20,'When you were slaves of sin, you were free in regard to righteousness.','当你们作罪恶的奴隶时，不受正义的束缚；');
INSERT INTO verse VALUES('Rom.6.21',52,6,21,'So what advantage did you then get from the things of which you now are ashamed? The end of those things is death.','但那时你们得了什么效果？只是叫你们现在以那些事为可耻，因为其结局就是死亡；');
INSERT INTO verse VALUES('Rom.6.22',52,6,22,'But now that you have been freed from sin and enslaved to God, the advantage you get is sanctification. The end is eternal life.','可是现在，你们脱离了罪恶，获得了自由，作了天主的奴隶，你们所得的效果是使你们成圣，结局就是永生。');
INSERT INTO verse VALUES('Rom.6.23',52,6,23,'For the wages of sin is death, but the free gift of God is eternal life in Christ Jesus our Lord.','因为罪恶的薪俸是死亡，但是天主的恩赐是在我们的主基督耶稣内的永生。');
